import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;

  // Root container
  const root = new Group();

  // Geometry – keep aspect close to the source atlas (512x320)
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  // Material
  const material = new MeshBasicNodeMaterial();
  material.opacity = 1.0;

  // Load texture (if any)
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  root.add(mesh);

  // Text content handling
  const items =
    config.textContent ??
    (config.intent && config.intent.visualSpec && config.intent.visualSpec.textContent) ??
    [];

  const textObjects = [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: (item.typography && item.typography.fontSize) || 39,
      color: (config.colors && config.colors.paper) || '#e8ecf2',
      align: 'left',
    });
    // Slightly lift the text above the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // Apply cinematic primitives if any
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && typeof prim.name === 'string' && ctx.primitives[prim.name]) {
        const instance = ctx.primitives[prim.name](root, prim.params || {});
        primitiveInstances.push(instance);
      }
    }
  }

  // Store cleanup & handlers in userData
  root.userData = {
    handlers: {},
    cleanup() {
      // Dispose geometry and material
      geometry.dispose();
      material.dispose();

      // Dispose texture if it was loaded
      if (loadedTexture && loadedTexture.dispose) {
        loadedTexture.dispose();
      }

      // Cleanup primitives
      for (const inst of primitiveInstances) {
        if (inst && typeof inst.cleanup === 'function') {
          inst.cleanup();
        }
      }

      // Kill any GSAP timelines that might have been created
      gsap.globalTimeline.clear();

      // Remove text objects (if they expose dispose)
      for (const txt of textObjects) {
        if (txt && txt.parent) {
          txt.parent.remove(txt);
        }
      }
    },
  };

  return root;
}
